import{c as a,Q as l,j as r,m as e}from"./chunks/framework.rWdQudnF.js";const _=JSON.parse('{"title":"调用返回风格","description":"","frontmatter":{"title":"调用返回风格"},"headers":[],"relativePath":"综合知识/架构设计/架构风格与模式/调用返回风格.md","filePath":"综合知识/架构设计/架构风格与模式/调用返回风格.md","lastUpdated":null}'),i={name:"综合知识/架构设计/架构风格与模式/调用返回风格.md"};function o(n,t,d,s,h,u){return l(),r("div",null,[...t[0]||(t[0]=[e('<blockquote><p>调用/返回风格的核心：构件间存在<strong>显式调用关系</strong>，采用<strong>分而治之</strong>策略。</p></blockquote><h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 主程序/子程序：单线程，过程调用</li><li>[ ] 面向对象：对象 + 消息调用</li><li>[ ] 层次结构：每层只影响相邻层</li><li>[ ] 层次结构的脆弱性</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="主程序-子程序" tabindex="-1">主程序/子程序 <a class="header-anchor" href="#主程序-子程序" aria-label="Permalink to &quot;主程序/子程序&quot;">​</a></h3><ul><li><strong>单线程控制</strong>，把问题划分为处理步骤</li><li>构件 = 主程序和子程序</li><li>连接件 = 过程调用</li></ul><h3 id="面向对象" tabindex="-1">面向对象 <a class="header-anchor" href="#面向对象" aria-label="Permalink to &quot;面向对象&quot;">​</a></h3><ul><li>构件 = <strong>对象</strong>（抽象数据类型的实例）</li><li>连接件 = 对象间交互方式（函数和过程调用）</li><li>核心思想：<strong>分而治之</strong>，将复杂系统分解为子系统</li></ul><h3 id="层次结构-高频考点" tabindex="-1">层次结构（高频考点） <a class="header-anchor" href="#层次结构-高频考点" aria-label="Permalink to &quot;层次结构（高频考点）&quot;">​</a></h3><ul><li>构件组成层次结构，每层为上一层提供服务，使用下一层服务</li><li>只能见到与自己邻接的层</li><li><strong>修改某一层，最多影响相邻两层（通常只影响上层）</strong></li><li>连接件 = 层间交互协议</li></ul><table tabindex="0"><thead><tr><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>支持可增加抽象层的设计</td><td>并非每个系统都能分层</td></tr><tr><td>不同层处于不同抽象级别</td><td>很难找到合适的抽象方法</td></tr><tr><td>接口相同则每层可不同实现</td><td><strong>通信效率较低</strong>（需高→低→高）</td></tr></tbody></table><h3 id="🎯-分层架构两大脆弱性" tabindex="-1">🎯 分层架构两大脆弱性 <a class="header-anchor" href="#🎯-分层架构两大脆弱性" aria-label="Permalink to &quot;🎯 分层架构两大脆弱性&quot;">​</a></h3><ol><li><strong>底层错误</strong>导致整个系统无法正常运行</li><li>层间引入通信机制造成<strong>性能下降</strong></li></ol>',13)])])}const b=a(i,[["render",o]]);export{_ as __pageData,b as default};
